(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[193],{1532:function(t,n,e){"use strict";e.r(n),n.default={code:"M3-03",title:"滑動視窗(sliding window)",tier:"t3",unlockCode:"M3-03-SlidingWindow",tasks:[{id:"M3-03-01",code:"M3-03-M3-03-01",title:"連續K天營收總和一覽",description:"商店記錄每天營收，請你算出所有『連續K天』區間的營收總和，依開始日期順序輸出。\n\n第一行輸入N，代表有N天\n\n第二行輸入N個數字，代表每天營收\n\n第三行輸入K\n\n輸出從第1天開始、第2天開始……一直到最後一個可能的K天區間，各自的總和，空白分隔。",examples:[{input:"5\n10 20 30 40 50\n3",output:"60 90 120",explanation:"第1~3天:10+20+30=60；第2~4天:20+30+40=90；第3~5天:30+40+50=120"}],testCases:[{input:"5\n10 20 30 40 50\n3",expectedOutput:"60 90 120",score:25},{input:"4\n1 2 3 4\n2",expectedOutput:"3 5 7",score:25},{input:"3\n5 5 5\n3",expectedOutput:"15",score:25},{input:"5\n1 1 1 1 1\n1",expectedOutput:"1 1 1 1 1",score:25}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M3-03-SlidingWindow/M3-03-01.sb3"},{id:"M3-03-02",code:"M3-03-M3-03-02",title:"連續K天最大總營收",description:"同樣是每日營收紀錄，請你找出『連續K天』區間中，總營收最高的金額是多少。\n\n第一行輸入N\n\n第二行輸入N個每日營收\n\n第三行輸入K\n\n輸出所有連續K天區間中的最大總營收。",examples:[{input:"5\n10 20 30 40 50\n3",output:"120",explanation:"所有連續3天總和中，30+40+50=120最大"}],testCases:[{input:"5\n10 20 30 40 50\n3",expectedOutput:"120",score:25},{input:"4\n1 2 3 4\n2",expectedOutput:"7",score:25},{input:"6\n5 1 5 9 5 1\n2",expectedOutput:"14",score:25},{input:"5\n9 1 1 1 9\n2",expectedOutput:"10",score:25}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-03-SlidingWindow/M3-03-02.sb3"},{id:"M3-03-03",code:"M3-03-M3-03-03",title:"連續K天最小總營收",description:"同樣是每日營收紀錄，請你找出『連續K天』區間中，總營收最低的金額是多少。\n\n第一行輸入N\n\n第二行輸入N個每日營收\n\n第三行輸入K\n\n輸出所有連續K天區間中的最小總營收。",examples:[{input:"5\n10 20 30 40 50\n3",output:"60",explanation:"所有連續3天總和中，10+20+30=60最小"}],testCases:[{input:"5\n10 20 30 40 50\n3",expectedOutput:"60",score:25},{input:"4\n1 2 3 4\n2",expectedOutput:"3",score:25},{input:"6\n5 1 5 9 5 1\n2",expectedOutput:"6",score:25},{input:"5\n9 1 1 1 9\n2",expectedOutput:"2",score:25}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-03-SlidingWindow/M3-03-03.sb3"},{id:"M3-03-04",code:"M3-03-M3-03-04",title:"連續K天平均是否曾經達標",description:"請你判斷是否存在某一段連續K天，平均營收達到門檻threshold以上（整數除法，無條件捨去）。只要存在至少一段就輸出「有」，否則輸出「無」。\n\n第一行輸入N\n\n第二行輸入N個每日營收\n\n第三行輸入K threshold（空白分隔）\n\n輸出「有」或「無」。",examples:[{input:"5\n10 20 30 40 50\n3 35",output:"有",explanation:"第3~5天平均(30+40+50)/3=40，大於等於35，所以有"}],testCases:[{input:"5\n10 20 30 40 50\n3 35",expectedOutput:"有",score:25},{input:"5\n10 20 30 40 50\n3 50",expectedOutput:"無",score:25},{input:"4\n1 2 3 4\n2 3",expectedOutput:"有",score:25},{input:"4\n1 2 3 4\n2 4",expectedOutput:"無",score:25}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-03-SlidingWindow/M3-03-04.sb3"},{id:"M3-03-05",code:"M3-03-M3-03-05",title:"最長連續達標天數",description:"請你找出最長一段『連續達標』的天數——只要每天的數值都大於等於門檻threshold，就算是達標；求最長連續達標的天數（如果完全沒有任何一天達標，輸出0）。\n\n第一行輸入N\n\n第二行輸入N個每日數值\n\n第三行輸入threshold",examples:[{input:"7\n5 8 9 3 10 12 11\n8",output:"3",explanation:"第2~3天(8,9)連續達標2天；第5~7天(10,12,11)連續達標3天最長"}],testCases:[{input:"7\n5 8 9 3 10 12 11\n8",expectedOutput:"3",score:25},{input:"5\n1 2 3 4 5\n10",expectedOutput:"0",score:25},{input:"5\n5 5 5 5 5\n5",expectedOutput:"5",score:25},{input:"6\n1 9 9 1 9 9\n9",expectedOutput:"2",score:25}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-03-SlidingWindow/M3-03-05.sb3"},{id:"M3-03-06",code:"M3-03-M3-03-06",title:"最少連續幾天達到目標總量",description:"請你找出最短的一段連續天數，讓這段天數的總和達到（大於等於）目標值target；如果找不到這樣的連續天數，輸出0。\n\n第一行輸入N\n\n第二行輸入N個每日數值\n\n第三行輸入target\n\n輸出最短的連續天數；找不到輸出0。",examples:[{input:"6\n2 3 1 2 4 3\n7",output:"2",explanation:"第5~6天4+3=7，只用2天就達標，是最短的"}],testCases:[{input:"6\n2 3 1 2 4 3\n7",expectedOutput:"2",score:25},{input:"5\n1 1 1 1 1\n100",expectedOutput:"0",score:25},{input:"3\n10 2 3\n10",expectedOutput:"1",score:25},{input:"5\n1 4 4 1 5\n8",expectedOutput:"2",score:25}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-03-SlidingWindow/M3-03-06.sb3"}]}}}]);